// =====================================================================
// PASO 1: VALIDACIÓN DE RESPUESTA GRAFANA Y FILTRO DE EXCLUSIONES
// =====================================================================
const input = $input.first().json;
if (input.statusCode && input.statusCode >= 400) {
  throw new Error(`Grafana error ${input.statusCode}: ${JSON.stringify(input.body || input).substring(0, 500)}`);
}
const responseData = input.results ? input : (input.body || input);
const frames = responseData.results?.A?.frames || [];
if (frames.length === 0) throw new Error('Grafana devolvió frames vacíos.');

const frame = frames[0];
const fields = frame.schema?.fields || [];
const values = frame.data?.values || [];

const colIndex = {};
fields.forEach((f, i) => { colIndex[f.name] = i; });

const rowCount = values[0]?.length || 0;
const rows = [];
for (let i = 0; i < rowCount; i++) {
  const row = {};
  fields.forEach((f, ci) => { row[f.name] = values[ci][i]; });
  rows.push(row);
}

const clientesExcluidosRaw = $env.CHURN_EXCLUDED_CLIENT_IDS || '';
const clientesExcluidosSet = new Set(clientesExcluidosRaw.split(',').map(id => id.trim().toLowerCase()).filter(Boolean));

const clientes = {};
for (const row of rows) {
  const id = String(row.cliente_id);
  if (clientesExcluidosSet.has(id.toLowerCase())) continue;
  if (!clientes[id]) clientes[id] = { id, nombre: row.cliente_nombre || `Cliente ${id}`, facturas: [] };
  clientes[id].facturas.push({ fecha: new Date(row.fecha_emision), monto: parseFloat(row.monto) || 0 });
}

return Object.values(clientes).map(c => ({ json: c }));

// =====================================================================
// PASO 2: CÁLCULO SEÑAL A (RECENCIA: SILENCIO vs CADENCIA)
// =====================================================================
const items = $input.all().map(i => i.json);
const hoy = new Date();
const hace6m = new Date(hoy);
hace6m.setMonth(hace6m.getMonth() - 6);

return items.map(cliente => {
  const facturas = cliente.facturas.map(f => ({ ...f, fecha: new Date(f.fecha) })).sort((a, b) => a.fecha - b.fecha);

  if (facturas.length < 2) {
    return { json: { ...cliente, facturas, estado_recencia: '⚪ Sin datos', nivel_recencia: 0, cadencia_dias: 0, silencio_dias: 0, ratio_recencia: 0, insuficiente_historia: true } };
  }

  const recientes = facturas.filter(f => f.fecha >= hace6m);
  let cadencia = 30;
  if (recientes.length >= 2) {
    const gaps = [];
    for (let i = 1; i < recientes.length; i++) {
      const diffDias = (recientes[i].fecha - recientes[i - 1].fecha) / 864e5;
      if (diffDias > 0) gaps.push(diffDias);
    }
    if (gaps.length > 0) {
      gaps.sort((a, b) => a - b);
      cadencia = gaps[Math.floor(gaps.length / 2)];
    }
  }

  const ultimaFactura = facturas[facturas.length - 1].fecha;
  const silencio = (hoy - ultimaFactura) / 864e5;
  const ratio = cadencia > 0 ? silencio / cadencia : 999;

  let estadoRecencia = '🟢 Normal', nivelRecencia = 0;
  if (ratio > 5) { estadoRecencia = '🔴 Rojo'; nivelRecencia = 3; }
  else if (ratio > 3) { estadoRecencia = '🟠 Naranja'; nivelRecencia = 2; }
  else if (ratio > 2) { estadoRecencia = '🟡 Amarillo'; nivelRecencia = 1; }

  return { json: { ...cliente, facturas, ultima_factura: ultimaFactura.toISOString().split('T')[0], cadencia_dias: Math.round(cadencia), silencio_dias: Math.round(silencio), ratio_recencia: Math.round(ratio * 100) / 100, estado_recencia: estadoRecencia, nivel_recencia: nivelRecencia, insuficiente_historia: false } };
});

// =====================================================================
// PASO 3: CÁLCULO SEÑAL B (CAÍDA DE VOLUMEN PROPORCIONAL)
// =====================================================================
const items = $input.all().map(i => i.json);
const hoy = new Date();
const diaDelMes = hoy.getDate();
const mesActualKey = `${hoy.getFullYear()}-${String(hoy.getMonth() + 1).padStart(2, '0')}`;

return items.map(cliente => {
  if (cliente.insuficiente_historia) {
    return { json: { ...cliente, estado_volumen: '⚪ Sin datos', nivel_volumen: 0, caida_volumen_pct: 0 } };
  }

  const mesesMap = {};
  for (const f of cliente.facturas) {
    const fecha = new Date(f.fecha);
    const key = `${fecha.getFullYear()}-${String(fecha.getMonth() + 1).padStart(2, '0')}`;
    if (!mesesMap[key]) mesesMap[key] = { total: 0, totalVentana: 0 };
    mesesMap[key].total++;
    if (fecha.getDate() <= diaDelMes) mesesMap[key].totalVentana++;
  }

  const mesesKeys = Object.keys(mesesMap).sort();
  const mesesPrevios = mesesKeys.filter(k => k !== mesActualKey).slice(-6);
  const valoresPrevios = mesesPrevios.map(k => mesesMap[k].totalVentana);

  let estadoVolumen = '🟢 Normal', nivelVolumen = 0, caidaPct = 0;
  if (valoresPrevios.length >= 2) {
    const sorted = [...valoresPrevios].sort((a, b) => a - b);
    const baseProporcional = sorted[Math.floor(sorted.length / 2)];
    const actual = mesesMap[mesActualKey]?.totalVentana || 0;

    if (baseProporcional > 0) {
      caidaPct = Math.round(((baseProporcional - actual) / baseProporcional) * 100);
      if (caidaPct >= 70) { estadoVolumen = '🔴 Rojo'; nivelVolumen = 3; }
      else if (caidaPct >= 50) { estadoVolumen = '🟠 Naranja'; nivelVolumen = 2; }
      else if (caidaPct >= 30) { estadoVolumen = '🟡 Amarillo'; nivelVolumen = 1; }
    }
  }

  return { json: { ...cliente, mesesMap, mesesKeys, estado_volumen: estadoVolumen, nivel_volumen: nivelVolumen, caida_volumen_pct: Math.max(caidaPct, 0) } };
});

// =====================================================================
// PASO 4: CÁLCULO SEÑAL C (RACHA DESCENDENTE DE 3 MESES)
// =====================================================================
const items = $input.all().map(i => i.json);
const hoy = new Date();
const mesActualKey = `${hoy.getFullYear()}-${String(hoy.getMonth() + 1).padStart(2, '0')}`;

return items.map(cliente => {
  if (cliente.insuficiente_historia) {
    return { json: { ...cliente, racha_descendente: false } };
  }

  const mesesKeys = cliente.mesesKeys || [];
  const mesesMap = cliente.mesesMap || {};
  const ultimos3 = mesesKeys.filter(k => k !== mesActualKey).slice(-3);
  let rachaDescendente = false;

  if (ultimos3.length === 3) {
    const v = ultimos3.map(k => mesesMap[k].total);
    if (v[0] > v[1] && v[1] > v[2]) rachaDescendente = true;
  }

  return { json: { ...cliente, racha_descendente: rachaDescendente } };
});

// =====================================================================
// PASO 5: AJUSTE ESTACIONALIDAD + CÁLCULO MRR ESTIMADO ($)
// =====================================================================
const items = $input.all().map(i => i.json);
const hoy = new Date();
const mesActualKey = `${hoy.getFullYear()}-${String(hoy.getMonth() + 1).padStart(2, '0')}`;

return items.map(cliente => {
  if (cliente.insuficiente_historia) {
    return { json: { ...cliente, mrr_estimado: 0, ajuste_estacional: 0, meses_historia: 0, estado_final: '⚪ Sin datos', nivel_numerico: 0 } };
  }

  // MRR Estimado
  const hace3m = new Date(hoy);
  hace3m.setMonth(hace3m.getMonth() - 3);
  const facturasUltimos3m = cliente.facturas.filter(f => new Date(f.fecha) >= hace3m);
  const mrrEstimado = Math.round(facturasUltimos3m.reduce((sum, f) => sum + f.monto, 0) / 3);

  // Estacionalidad
  const mesesKeys = cliente.mesesKeys || [];
  const mesesMap = cliente.mesesMap || {};
  const mesesHistoria = mesesKeys.length;
  let ajusteEstacional = 0;

  if (mesesHistoria >= 12) {
    const mesActualNum = hoy.getMonth() + 1;
    const keyAnioAnt = `${hoy.getFullYear() - 1}-${String(mesActualNum).padStart(2, '0')}`;
    const volMesAnioAnt = mesesMap[keyAnioAnt]?.totalVentana || 0;
    const volMesActual = mesesMap[mesActualKey]?.totalVentana || 0;
    if (volMesAnioAnt > 0 && volMesActual > 0) {
      if (Math.abs((volMesActual - volMesAnioAnt) / volMesAnioAnt) <= 0.2 && (cliente.nivel_recencia > 0 || cliente.nivel_volumen > 0)) {
        ajusteEstacional = -1;
      }
    }
  }

  // Combinación Final
  let nivelFinal = Math.max(cliente.nivel_recencia, cliente.nivel_volumen);
  if (cliente.racha_descendente && nivelFinal > 0) {
    nivelFinal = Math.min(nivelFinal + 1, 3);
  }
  nivelFinal = Math.max(nivelFinal + ajusteEstacional, 0);

  const estadoMap = { 0: '🟢 Normal', 1: '🟡 Amarillo', 2: '🟠 Naranja', 3: '🔴 Rojo' };

  // Limpiar campos temporales de cálculo
  delete cliente.mesesMap;
  delete cliente.mesesKeys;

  return { json: { ...cliente, mrr_estimado: mrrEstimado, ajuste_estacional: ajusteEstacional, meses_historia: mesesHistoria, estado_final: estadoMap[nivelFinal], nivel_numerico: nivelFinal, fecha_analisis: hoy.toISOString().split('T')[0] } };
});

// =====================================================================
// PASO 6: TRANSICIONES Y REGLA DE PERSISTENCIA (3 DÍAS SEGUIDOS)
// Detecta cambios de estado en AMBAS direcciones: riesgo y crecimiento.
// =====================================================================
const hoyItems = $('Señal D: Desvío Positivo').all().map(i => i.json);
let ayerItems = [];
try { ayerItems = $('Leer Sheet (estado ayer)').all().map(i => i.json); } catch (e) {}
ayerItems = ayerItems.filter(item => item.cliente_id && String(item.cliente_id).trim() !== '');
const esPrimeraCorrida = ayerItems.length === 0;

// Los campos calculados en Estacionalidad & MRR se toman de ese nodo
const calcMap = {};
for (const it of $('Estacionalidad & MRR').all()) {
  calcMap[String(it.json.cliente_id)] = it.json;
}

const ayerMap = {};
for (const item of ayerItems) {
  ayerMap[String(item.cliente_id)] = {
    estado_final: item.estado_final || '🟢 Normal',
    nivel_numerico: parseInt(item.nivel_numerico) || 0,
    nivel_positivo: parseInt(item.nivel_positivo) || 0,
    dias_consecutivos_riesgo: parseInt(item.dias_consecutivos_riesgo) || 0
  };
}

return hoyItems.map(base => {
  const cid = String(base.cliente_id);
  const cliente = calcMap[cid] || base;
  const ayer = ayerMap[cid];

  const nivelAyer   = ayer ? ayer.nivel_numerico : 0;
  const nivelHoy    = cliente.nivel_numerico;
  const estadoAyer  = ayer ? ayer.estado_final : '🟢 Normal';
  const diasPrevioRiesgo = ayer ? ayer.dias_consecutivos_riesgo : 0;

  const nivelPosAyer = ayer ? ayer.nivel_positivo : 0;
  const nivelPosHoy  = cliente.nivel_positivo || 0;

  let diasConsecutivosRiesgo = 0;
  if (nivelHoy > 0) diasConsecutivosRiesgo = diasPrevioRiesgo + 1;

  let cumplePersistencia = true;
  if (cliente.meses_historia < 12 && nivelHoy > 0) {
    cumplePersistencia = diasConsecutivosRiesgo >= 3;
  }

  const empeoro = !esPrimeraCorrida && nivelHoy > nivelAyer && nivelHoy > 0 && cumplePersistencia;
  const mejoro  = !esPrimeraCorrida && nivelHoy < nivelAyer && nivelAyer > 0;

  // Desvío positivo: solo se reporta al ENTRAR o al SUBIR de nivel
  const entroCrecimiento = !esPrimeraCorrida && nivelPosHoy > nivelPosAyer && nivelPosHoy > 0;

  const transicion = esPrimeraCorrida
    ? `🆕 Primera lectura: ${cliente.estado_final}`
    : (estadoAyer !== cliente.estado_final ? `${estadoAyer} → ${cliente.estado_final}` : 'Sin cambio');

  return { json: { ...cliente,
    estado_ayer: esPrimeraCorrida ? 'N/A' : estadoAyer,
    dias_consecutivos_riesgo: diasConsecutivosRiesgo,
    transicion, empeoro, mejoro,
    entro_crecimiento: entroCrecimiento,
    nivel_positivo_ayer: nivelPosAyer,
    es_primera_corrida: esPrimeraCorrida } };
});

// =====================================================================
// PASO 7: RESUMEN DIARIO ÚNICO PARA #engagement-team
// Requisito de Tomás (30/07/2026): máximo 1 mensaje por día, con TODOS
// los desvíos juntos, positivos y negativos. Solo los que cambiaron.
// =====================================================================
const items = $input.all().map(i => i.json);
const esPrimeraCorrida = items[0]?.es_primera_corrida || false;
const ENVIAR_SIN_DESVIOS = String($env.CHURN_ENVIAR_SIN_DESVIOS || 'false') === 'true';

const fmtUSD  = v => '$' + (v || 0).toLocaleString('en-US');
const sheetUrl = $env.CHURN_SHEET_URL || 'https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit';
const hoy = new Date();
const fechaCorta = `${String(hoy.getDate()).padStart(2,'0')}/${String(hoy.getMonth()+1).padStart(2,'0')}`;
const porMrr = (a, b) => (b.mrr_estimado || 0) - (a.mrr_estimado || 0);

// ---------- Línea base (primera corrida) ----------
if (esPrimeraCorrida) {
  const total = items.length;
  const sinDatos  = items.filter(i => (i.estado_final || '').includes('Sin datos'));
  const amarillos = items.filter(i => i.nivel_numerico === 1);
  const naranjas  = items.filter(i => i.nivel_numerico === 2);
  const rojos     = items.filter(i => i.nivel_numerico === 3);
  const verdes    = items.filter(i => i.nivel_numerico === 0).length - sinDatos.length;
  const crecen    = items.filter(i => (i.nivel_positivo || 0) > 0);
  const mrrRiesgo = [...rojos, ...naranjas, ...amarillos].reduce((s, c) => s + (c.mrr_estimado || 0), 0);

  let msg = `📊 *Desvíos de facturación — Línea base*\n\n`;
  msg += `Se analizaron *${total}* clientes (MRR en riesgo: *${fmtUSD(mrrRiesgo)}*)\n`;
  msg += `• 🟢 Normal: ${verdes}\n`;
  if (sinDatos.length)  msg += `• ⚪ Sin datos suficientes: ${sinDatos.length}\n`;
  if (amarillos.length) msg += `• 🟡 Atención: ${amarillos.length}\n`;
  if (naranjas.length)  msg += `• 🟠 Caída moderada: ${naranjas.length}\n`;
  if (rojos.length)     msg += `• 🔴 Caída fuerte: ${rojos.length}\n`;
  if (crecen.length)    msg += `• 🟢 Crecimiento: ${crecen.length}\n`;

  const enRiesgo = [...rojos, ...naranjas].sort(porMrr);
  if (enRiesgo.length) {
    msg += `\n⚠️ *Mayor impacto:*\n`;
    enRiesgo.slice(0, 10).forEach(c => {
      msg += `• *${c.cliente_nombre}* — ${c.estado_final} · MRR ${fmtUSD(c.mrr_estimado)} · silencio ${c.silencio_dias}d\n`;
    });
    if (enRiesgo.length > 10) msg += `  _…y ${enRiesgo.length - 10} más_\n`;
  }
  msg += `\n_Desde mañana se reportan solo los cambios de estado._\n📋 <${sheetUrl}|Ver tablero completo>`;
  return [{ json: { slack_message: msg, tiene_alerta: true, tipo: 'linea_base', empeorados: [] } }];
}

// ---------- Resumen diario ----------
const empeorados = items.filter(i => i.empeoro);
const crecimiento = items.filter(i => i.entro_crecimiento).sort(porMrr);
const mejorados  = items.filter(i => i.mejoro).sort(porMrr);

const rojos    = empeorados.filter(c => c.nivel_numerico === 3).sort(porMrr);
const naranjas = empeorados.filter(c => c.nivel_numerico === 2).sort(porMrr);
const amarillos= empeorados.filter(c => c.nivel_numerico === 1).sort(porMrr);

const hayAlgo = empeorados.length || crecimiento.length || mejorados.length;
if (!hayAlgo && !ENVIAR_SIN_DESVIOS) {
  return [{ json: { slack_message: '', tiene_alerta: false, tipo: 'sin_desvios', empeorados: [] } }];
}
if (!hayAlgo) {
  return [{ json: { slack_message: `📊 *Desvíos de facturación — ${fechaCorta}*\n\nSin desvíos hoy. 👌\n📋 <${sheetUrl}|Ver tablero>`,
                    tiene_alerta: true, tipo: 'sin_desvios', empeorados: [] } }];
}

// Línea de detalle de una caída
const lineaCaida = c => {
  let l = `• *${c.cliente_nombre}* — `;
  const partes = [];
  if (c.silencio_dias && c.cadencia_dias) partes.push(`sin facturar hace ${c.silencio_dias} días (habitual: cada ${c.cadencia_dias})`);
  if (c.caida_volumen_pct > 0) partes.push(`−${c.caida_volumen_pct}%`);
  if (c.racha_descendente) partes.push('3er mes consecutivo en baja');
  if (c.ajuste_estacional < 0) partes.push('ajustado por estacionalidad');
  l += partes.join(' · ');
  l += ` · MRR ${fmtUSD(c.mrr_estimado)}\n`;
  return l;
};

// Línea de crecimiento — SIEMPRE con el dato crudo al lado del %
const lineaCrecimiento = c => {
  let l = `• *${c.cliente_nombre}* — `;
  const partes = [];
  if (c.suba_volumen_pct > 0) {
    partes.push(`+${c.suba_volumen_pct}% (${c.facturas_actual} facturas vs. ${c.facturas_habitual} habituales)`);
  }
  if (c.aceleracion_cadencia) partes.push('factura más seguido que lo habitual');
  l += partes.join(' · ');
  l += ` · MRR ${fmtUSD(c.mrr_estimado)}\n`;
  return l;
};

let msg = `📊 *Desvíos de facturación — ${fechaCorta}*\n`;

if (rojos.length)     { msg += `\n🔴 *Caída fuerte (${rojos.length})*\n`;      rojos.forEach(c => msg += lineaCaida(c)); }
if (naranjas.length)  { msg += `\n🟠 *Caída moderada (${naranjas.length})*\n`; naranjas.forEach(c => msg += lineaCaida(c)); }
if (amarillos.length) { msg += `\n🟡 *Atención (${amarillos.length})*\n`;      amarillos.forEach(c => msg += lineaCaida(c)); }
if (crecimiento.length){ msg += `\n🟢 *Crecimiento (${crecimiento.length})*\n`; crecimiento.forEach(c => msg += lineaCrecimiento(c)); }
if (mejorados.length) {
  msg += `\n✅ *Se recuperaron (${mejorados.length})*\n`;
  mejorados.forEach(c => msg += `• *${c.cliente_nombre}* — ${c.transicion} · MRR ${fmtUSD(c.mrr_estimado)}\n`);
}

msg += `\n_Solo aparecen los que cambiaron de estado respecto de ayer._\n`;
msg += `📋 <${sheetUrl}|Ver cartera completa>`;

return [{ json: { slack_message: msg, tiene_alerta: true, tipo: 'resumen_diario',
                  empeorados, total_desvios: empeorados.length + crecimiento.length } }];

// =====================================================================
// PASO 4b: SEÑAL D (DESVÍO POSITIVO: CRECIMIENTO ATÍPICO)
// Detecta subas de volumen y aceleración de cadencia contra la propia
// base histórica del cliente. Categoría INDEPENDIENTE: no escala la
// gravedad de churn, se reporta por separado.
// =====================================================================
const items = $input.all().map(i => i.json);
const hoy = new Date();
const diaDelMes = hoy.getDate();
const mesActualKey = `${hoy.getFullYear()}-${String(hoy.getMonth() + 1).padStart(2, '0')}`;

// Umbral configurable: % de suba sobre su base para marcar crecimiento
const UMBRAL = parseInt($env.CHURN_UMBRAL_POSITIVO) || 50;

return items.map(cliente => {
  if (cliente.insuficiente_historia) {
    return { json: { ...cliente, estado_positivo: '', nivel_positivo: 0, suba_volumen_pct: 0,
                     facturas_actual: 0, facturas_habitual: 0, aceleracion_cadencia: false } };
  }

  const mesesMap  = cliente.mesesMap  || {};
  const mesesKeys = cliente.mesesKeys || [];
  const mesesPrevios = mesesKeys.filter(k => k !== mesActualKey).slice(-6);
  const valoresPrevios = mesesPrevios.map(k => mesesMap[k].totalVentana);

  const actual = mesesMap[mesActualKey]?.totalVentana || 0;
  let base = 0, subaPct = 0, nivelPositivo = 0, estadoPositivo = '';

  // Misma ventana temporal que Señal B (día 1 al día actual)
  if (valoresPrevios.length >= 2) {
    const sorted = [...valoresPrevios].sort((a, b) => a - b);
    base = sorted[Math.floor(sorted.length / 2)];
    if (base > 0 && actual > base) {
      subaPct = Math.round(((actual - base) / base) * 100);
      if (subaPct >= UMBRAL * 2)  { estadoPositivo = '🟢 Crecimiento fuerte'; nivelPositivo = 2; }
      else if (subaPct >= UMBRAL) { estadoPositivo = '🟢 Crecimiento';        nivelPositivo = 1; }
    }
  }

  // Aceleración de cadencia: factura notablemente más seguido que su mediana
  let aceleracion = false;
  const hace30 = new Date(hoy); hace30.setDate(hace30.getDate() - 30);
  const recientes = (cliente.facturas || [])
    .map(f => new Date(f.fecha))
    .filter(d => d >= hace30)
    .sort((a, b) => a - b);
  if (recientes.length >= 3 && cliente.cadencia_dias > 0) {
    const gaps = [];
    for (let i = 1; i < recientes.length; i++) {
      const d = (recientes[i] - recientes[i - 1]) / 864e5;
      if (d > 0) gaps.push(d);
    }
    if (gaps.length > 0) {
      gaps.sort((a, b) => a - b);
      const cadReciente = gaps[Math.floor(gaps.length / 2)];
      if (cadReciente > 0 && cadReciente <= cliente.cadencia_dias / 2) {
        aceleracion = true;
        if (nivelPositivo === 0) { nivelPositivo = 1; estadoPositivo = '🟢 Crecimiento'; }
      }
    }
  }

  return { json: { ...cliente,
    suba_volumen_pct: subaPct,
    nivel_positivo: nivelPositivo,
    estado_positivo: estadoPositivo,
    facturas_actual: actual,       // dato CRUDO: distingue crecimiento de carga acumulada
    facturas_habitual: base,
    aceleracion_cadencia: aceleracion } };
});
